-- ════ SECTION O CONTINUES · O 3 · similar questions (part 12 of supabase/parts) ════
-- ── O 3 (release B): similar questions ("שאלות דומות") ──
--  docs/study/sheets.md ("SQL section O 3"); design-exams §7.3, D16-D22,
--  D24; practice sets §13.2 (a run's questions are a practice set of kind
--  'sheet' in section L, made through qset_for_similar, qset_add_items and
--  qset_similar_done; no share function, page or notice of O's own).
--  A similar question ("a twin") is its own row: source 'twin', twin_of the
--  source item (its root), from_exam the sheet, no exam_id and no lecture,
--  so S's and O's readers of an upload (s=e., the review, exam_advance)
--  never see it, and the group-wide pickers leave it out (q_plain). Only
--  checked twins are saved (twin_check: recomputed, a blind solve, or the
--  slides' solver). A run is made on a member's tap (op "similar"): one
--  item (up to 2 twins, at most 6 a root) or the whole sheet (one twin each
--  for up to 24 items, once a sheet a day), reserved whole under the member
--  (kind 'similar') and charged call by call (study_similar_charge); its jobs
--  run in study_private.similar_jobs through /api/study/work {similar}, kicked
--  by its own sweeper, and share the group's three at once with summaries
--  and exams (group_live). The switch 'similar' is inserted off. In place
--  elsewhere: section F's and L's kind_on ('similar'), section E's source
--  check (kept when wider). Every call into L and R is guarded.

-- Part 12 runs after part 11: O 3 builds on O 2's columns and functions.
do $$
begin
  if coalesce((select s.version from study_private.schema_sections s where s.section = 'O'), 0) < 2 then
    raise exception 'section O 3 needs part 11 run first (section O is not at 2 yet)';
  end if;
end $$;

-- ── Columns and checks ──
alter table public.study_questions
  add column if not exists from_exam  uuid references public.study_exams (id) on delete cascade,
  add column if not exists twin_check text;
create index if not exists study_questions_from_exam on public.study_questions (from_exam, twin_of) where from_exam is not null;
create index if not exists study_questions_twin_of on public.study_questions (twin_of) where twin_of is not null;
do $$
declare c record;
begin
  -- The source: + 'twin' (section E's check, which E now keeps once it is wider).
  if exists (select 1 from pg_constraint x where x.conname = 'study_questions_source_check' and x.conrelid = 'public.study_questions'::regclass
              and pg_get_constraintdef(x.oid) not like '%twin%') then
    alter table public.study_questions drop constraint study_questions_source_check;
  end if;
  if not exists (select 1 from pg_constraint x where x.conname = 'study_questions_source_check' and x.conrelid = 'public.study_questions'::regclass) then
    alter table public.study_questions add constraint study_questions_source_check check (source in ('ai', 'exam', 'member', 'twin'));
  end if;
  -- Section Q's inline "an exam item, or a lecture's" and "only an exam item names a lecture to read",
  -- found by their definitions: a twin has no lecture and keeps its sheet's as ref_lecture.
  for c in select x.conname from pg_constraint x
            where x.conrelid = 'public.study_questions'::regclass and x.contype = 'c'
              and x.conname not in ('study_questions_lecture_x', 'study_questions_ref_x')
              and (pg_get_constraintdef(x.oid) like '%(source = ''exam''::text) OR (lecture_id IS NOT NULL)%'
                   or pg_get_constraintdef(x.oid) like '%(source = ''exam''::text) OR (ref_lecture IS NULL)%') loop
    execute format('alter table public.study_questions drop constraint %I', c.conname);
  end loop;
  if not exists (select 1 from pg_constraint where conname = 'study_questions_lecture_x') then
    alter table public.study_questions add constraint study_questions_lecture_x check (source in ('exam', 'twin') or lecture_id is not null);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'study_questions_ref_x') then
    alter table public.study_questions add constraint study_questions_ref_x check (source in ('exam', 'twin') or ref_lecture is null);
  end if;
  -- A twin's shape (twin_of may become null: its root removed; the twin stays with its sheet).
  if not exists (select 1 from pg_constraint where conname = 'study_questions_twin_x') then
    alter table public.study_questions add constraint study_questions_twin_x check (
      (source = 'twin') = (from_exam is not null)
      and (source <> 'twin' or (exam_id is null and lecture_id is null and exam_no is null and twin_check in ('recalc', 'blind', 'slides')))
      and (source = 'twin' or twin_check is null));
  end if;
  -- The key's origin and the worked solution's: + 'twin' (S's and O 2's checks are added only when missing).
  if exists (select 1 from pg_constraint x where x.conname = 'study_question_keys_origin_x' and pg_get_constraintdef(x.oid) not like '%twin%') then
    alter table public.study_question_keys drop constraint study_question_keys_origin_x;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'study_question_keys_origin_x') then
    alter table public.study_question_keys add constraint study_question_keys_origin_x
      check ((key_origin is null or key_origin in ('exam', 'sheet', 'solved', 'member', 'twin')) and (key_conf is null or key_conf between 1 and 3));
  end if;
  if exists (select 1 from pg_constraint x where x.conname = 'study_question_keys_sheet_x' and pg_get_constraintdef(x.oid) not like '%twin%') then
    alter table public.study_question_keys drop constraint study_question_keys_sheet_x;
  end if;
  if not exists (select 1 from pg_constraint where conname = 'study_question_keys_sheet_x') then
    alter table public.study_question_keys add constraint study_question_keys_sheet_x check (
      (num_tol is null or num_tol between 0 and 50) and (num_unit is null or char_length(num_unit) <= 30)
      and (model_answer is null or char_length(model_answer) <= 2000) and cardinality(rubric) <= 6
      and (solution is null or char_length(solution) <= 6000)
      and (solution_origin is null or solution_origin in ('exam', 'sheet', 'solved', 'member', 'twin'))
      and (solution_conf is null or solution_conf between 1 and 3));
  end if;
end $$;

-- ── Runs (members read their group's; nobody writes them directly) and their jobs ──
create table if not exists public.study_similar_runs (
  id           uuid         primary key default gen_random_uuid(),
  group_id     uuid         not null references public.study_groups (id) on delete cascade,
  exam_id      uuid         not null references public.study_exams (id) on delete cascade,
  scope        text         not null check (scope in ('item', 'sheet')),
  items        uuid[]       not null check (cardinality(items) between 1 and 24),   -- the roots, in printed order
  per          smallint     not null check (per between 1 and 2),
  status       text         not null default 'running' check (status in ('running', 'done', 'failed', 'stopped')),
  made         int          not null default 0 check (made >= 0),
  dropped      int          not null default 0 check (dropped >= 0),
  skipped_figs int          not null default 0 check (skipped_figs >= 0),
  error        text         check (char_length(error) <= 200),
  reserve_id   bigint,                       -- the member's reservation in study_usage (kind 'similar', ref 'ask')
  reserved_usd numeric(8,4) not null check (reserved_usd > 0 and reserved_usd < 100),
  charged_usd  numeric(8,4) not null default 0 check (charged_usd >= 0),
  set_id       uuid,                         -- section L's set (kind 'sheet'), when L is installed
  created_by   uuid         not null default auth.uid() references auth.users (id) on delete cascade,
  created_at   timestamptz  not null default now(),
  updated_at   timestamptz  not null default now()
);
create index if not exists study_similar_runs_exam on public.study_similar_runs (exam_id, created_at desc);
create index if not exists study_similar_runs_live on public.study_similar_runs (group_id) where status = 'running';

create table if not exists study_private.similar_jobs (
  id          uuid        primary key default gen_random_uuid(),
  run_id      uuid        not null references public.study_similar_runs (id) on delete cascade,
  group_id    uuid        not null references public.study_groups (id) on delete cascade,
  items       uuid[]      not null check (cardinality(items) between 1 and 8),
  status      text        not null default 'pending' check (status in ('pending', 'running', 'done', 'failed')),
  lease_id    uuid,
  lease_until timestamptz,
  attempts    int         not null default 0,
  retry_at    timestamptz,
  made        int         not null default 0 check (made >= 0),
  dropped     int         not null default 0 check (dropped >= 0),
  skipped     int         not null default 0 check (skipped >= 0),   -- roots left out: a figure without a fresh link
  error       text,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);
create index if not exists similar_jobs_run on study_private.similar_jobs (run_id, status);
create index if not exists similar_jobs_live on study_private.similar_jobs (group_id) where status = 'running';
-- The roots a job saved twins for already: a job claimed again (its finish
-- lost after its save) writes only the others, and is done once none is left.
alter table study_private.similar_jobs add column if not exists done_roots uuid[] not null default '{}';

-- A running run's kicks and the pages' fresh links (D24), as exam_queue's.
create table if not exists study_private.similar_queue (
  run_id            uuid        primary key references public.study_similar_runs (id) on delete cascade,
  group_id          uuid        not null references public.study_groups (id) on delete cascade,
  urls              jsonb,
  urls_until        timestamptz,
  queued_at         timestamptz not null default now(),
  last_kick_at      timestamptz,
  kicks_since_claim int         not null default 0
);

alter table public.study_similar_runs enable row level security;
alter table study_private.similar_jobs enable row level security;
alter table study_private.similar_queue enable row level security;
drop policy if exists "study similar runs read" on public.study_similar_runs;
create policy "study similar runs read" on public.study_similar_runs for select using (public.study_is_member(group_id));
revoke all on public.study_similar_runs from anon, authenticated;
grant select on public.study_similar_runs to authenticated;
revoke all on study_private.similar_jobs, study_private.similar_queue from public, anon, authenticated;

-- The switch: off until Yoad turns it on (release B).
insert into study_private.features (name) values ('similar') on conflict (name) do nothing;

-- Roots a job of the whole sheet takes (an item's run is one job): 4, the
-- sheet solver's measured unit (sheets.md, "How long a unit takes"), until
-- Yoad's speed query says more fit; SIMILAR_JOB_ROOTS
-- (shared/study/sheetPrice.ts) is the same number (a unit test pins them).
create or replace function study_private.similar_job_roots()
returns int language sql immutable as $$ select 4 $$;

-- ── Which items can have similar questions ──

-- A question's root: a twin's source; then the first part of a question with parts.
create or replace function study_private.similar_root(p_question uuid)
returns uuid language sql stable security definer set search_path = public as $$
  with q as (select case when x.source = 'twin' then x.twin_of else x.id end as id from public.study_questions x where x.id = p_question)
  select coalesce((select h.id from public.study_questions r join public.study_questions h on h.series = r.series and h.exam_id = r.exam_id
                    where r.id = q.id and r.series is not null order by h.step, h.id limit 1), q.id)
    from q
$$;

-- The root's parts, in order (itself alone when it has none).
create or replace function study_private.similar_parts(p_root uuid)
returns setof uuid language sql stable security definer set search_path = public as $$
  select x.id from public.study_questions r join public.study_questions x
    on x.id = r.id or (r.series is not null and x.series = r.series and x.exam_id = r.exam_id)
   where r.id = p_root
   order by coalesce(x.step, 1), x.id
$$;

-- How many twins a root has (a twin with parts counts once).
create or replace function study_private.similar_count(p_root uuid)
returns int language sql stable security definer set search_path = public as $$
  select count(distinct coalesce(t.series, t.id))::int from public.study_questions t
   where t.source = 'twin' and t.retired_at is null and t.twin_of in (select study_private.similar_parts(p_root))
$$;

-- A root similar questions can be made of (design D17, OD11): a live item of
-- this sheet, a choice form (one, true/false, match, order) or a number,
-- every part too; keyed, and not only by a model's guess under confidence 3
-- (it counts in no score, so nothing is built on it). Never an open item.
create or replace function study_private.similar_ok(p_root uuid, p_exam uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.study_questions r where r.id = p_root and r.exam_id = p_exam and r.source = 'exam')
     and not exists (
       select 1 from study_private.similar_parts(p_root) pid join public.study_questions x on x.id = pid
         left join public.study_question_keys k on k.question_id = x.id
        where x.retired_at is not null or x.hidden_at is not null
           or x.form not in ('one', 'tf', 'match', 'order', 'numeric')
           or (x.form = 'numeric' and k.num is null)
           or (x.form <> 'numeric' and study_private.exam_unkeyed(x.id))
           or (k.key_origin = 'solved' and coalesce(k.key_conf, 0) < 3))
$$;

-- The pages of a root's figures (its boxes, or the one figure of an exam item).
create or replace function study_private.similar_fig_pages(p_root uuid)
returns int[] language sql stable security definer set search_path = public as $$
  select coalesce(array_agg(distinct split_part(f, ':', 2)::int order by split_part(f, ':', 2)::int), '{}')
    from study_private.similar_parts(p_root) pid join public.study_questions x on x.id = pid
         cross join lateral unnest(case when cardinality(coalesce(x.figures, '{}')) > 0 then x.figures
                                        when x.figure like 'pg:%' then array[x.figure] else '{}'::text[] end) f
$$;

-- The sheet as a member may make similar questions of it: the caller's
-- group's, not deleted, a sheet; the three switches. 'exam not found', 'off'.
create or replace function study_private.similar_sheet(p_exam uuid)
returns public.study_exams language plpgsql stable security definer set search_path = public as $$
declare e public.study_exams;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  select * into e from public.study_exams x where x.id = p_exam;
  if not found or e.deleted_at is not null or e.kind <> 'sheet' or not coalesce(public.study_is_member(e.group_id), false) then
    raise exception 'exam not found';
  end if;
  if not study_private.feature_on('exams') or not study_private.feature_on('sheets') or not study_private.feature_on('similar') then
    raise exception 'off';
  end if;
  return e;
end;
$$;

-- A run on this sheet that will still run: a job pending, retrying, or holding a live lease.
create or replace function study_private.similar_live(p_run uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from study_private.similar_jobs j
                  where j.run_id = p_run
                    and (j.status = 'pending' or (j.status = 'running' and j.lease_until > now())
                         or (j.status = 'failed' and j.attempts < 4 and j.retry_at is not null)))
$$;

-- The sheet's roots without a twin, in printed order (at most 24 go in a run).
create or replace function study_private.similar_open_roots(p_exam uuid)
returns setof uuid language sql stable security definer set search_path = public as $$
  select q.id from public.study_questions q
   where q.exam_id = p_exam and q.source = 'exam' and q.retired_at is null
     and (q.series is null or q.id = study_private.similar_root(q.id))
     and study_private.similar_ok(q.id, p_exam) and study_private.similar_count(q.id) = 0
   order by q.exam_no nulls last, coalesce(q.step, 1), q.id
$$;

-- The pages' fresh links (D24): each a signed link of this project for exactly that page of the sheet.
create or replace function study_private.similar_urls_ok(p_exam uuid, p_urls jsonb)
returns boolean language plpgsql stable security definer set search_path = public as $$
declare k text; v text;
begin
  if p_urls is null then return true; end if;
  if jsonb_typeof(p_urls) <> 'object' or length(p_urls::text) > 200000 then return false; end if;
  for k, v in select x.key, x.value from jsonb_each_text(p_urls) x loop
    if not exists (select 1 from public.study_exam_pages p where p.exam_id = p_exam and p.path = k)
       or v is null or v !~ '^https://[^/?#@]+/storage/v1/object/sign/study/[^?#]+\?token=[A-Za-z0-9._-]+$'
       or right(split_part(v, '?', 1), char_length('/storage/v1/object/sign/study/' || k)) <> '/storage/v1/object/sign/study/' || k then
      return false;
    end if;
  end loop;
  return true;
end;
$$;

-- ── "עוד שאלות כמוה" / "שאלות דומות לכל הדף": what a tap would make (read only) ──
-- p_scope 'item' (p_question: an item of the sheet, a part or one of its
-- twins: its root counts) or 'sheet'. Item: {scope, root, label, form,
-- count, room (6 less the twins it has), twins (theirs, free to practise),
-- joined (a run making some now), pages (its figures' pages)}. Sheet:
-- {scope, items (up to 24 roots without a twin, in printed order), more
-- (how many beyond 24), forms, today (a run of the whole sheet already
-- today), joined, pages}. 'not signed in', 'exam not found', 'off',
-- 'question not found', 'not eligible' (an open item, one without a sure key).
-- Whether a run of the whole sheet uses up the sheet's day (once a day):
-- one still making, one that made something, or one that paid for calls
-- (a run whose every twin was dropped still spent; one that stopped before
-- its first call did not).
create or replace function study_private.similar_today(x public.study_similar_runs)
returns boolean language sql stable as $$
  select x.status = 'running' or x.made > 0 or x.charged_usd > 0
$$;
revoke all on function study_private.similar_today(public.study_similar_runs) from public;

create or replace function public.study_similar_plan(p_exam uuid, p_question uuid default null, p_scope text default 'item')
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  e     public.study_exams;
  r     uuid;
  ids   uuid[];
  v_day timestamptz := date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem';
begin
  e := study_private.similar_sheet(p_exam);
  if p_scope = 'item' then
    r := study_private.similar_root(p_question);
    if r is null or not exists (select 1 from public.study_questions q where q.id = r and q.exam_id = p_exam) then
      raise exception 'question not found';
    end if;
    if not study_private.similar_ok(r, p_exam) then raise exception 'not eligible'; end if;
    return jsonb_build_object(
      'scope', 'item', 'root', r,
      'label', (select coalesce(q.no_label, q.exam_no::text) from public.study_questions q where q.id = r),
      'form', (select q.form from public.study_questions q where q.id = r),
      'parts', (select count(*) from study_private.similar_parts(r)),
      'numeric', (select count(*) from study_private.similar_parts(r) pid join public.study_questions x on x.id = pid where x.form = 'numeric'),
      'count', study_private.similar_count(r),
      'room', greatest(0, 6 - study_private.similar_count(r)),
      'twins', coalesce((select jsonb_agg(t.id order by t.created_at, coalesce(t.step, 1))
                           from public.study_questions t
                          where t.source = 'twin' and t.retired_at is null and t.hidden_at is null
                            and t.twin_of in (select study_private.similar_parts(r))), '[]'),
      'joined', (select x.id from public.study_similar_runs x
                  where x.exam_id = p_exam and x.status = 'running' and r = any (x.items) and study_private.similar_live(x.id)
                  order by x.created_at desc limit 1),
      'pages', to_jsonb(study_private.similar_fig_pages(r)));
  elsif p_scope = 'sheet' then
    ids := array(select study_private.similar_open_roots(p_exam));
    return jsonb_build_object(
      'scope', 'sheet',
      'items', to_jsonb(coalesce(ids[1:24], '{}')),
      'more', greatest(0, coalesce(cardinality(ids), 0) - 24),
      'forms', coalesce((select jsonb_agg(q.form order by array_position(ids, q.id)) from public.study_questions q where q.id = any (ids[1:24])), '[]'),
      'parts', coalesce((select sum((select count(*) from study_private.similar_parts(u)))::int from unnest(ids[1:24]) u), 0),
      -- each root's shape, for the price and the worst case: its parts, how many are numbers, its figures' pages
      'roots', coalesce((select jsonb_agg(jsonb_build_object(
                   'id', u, 'parts', (select count(*) from study_private.similar_parts(u)),
                   'numeric', (select count(*) from study_private.similar_parts(u) pid join public.study_questions x on x.id = pid where x.form = 'numeric'),
                   'pages', to_jsonb(study_private.similar_fig_pages(u))) order by o)
                   from unnest(ids[1:24]) with ordinality t(u, o)), '[]'),
      'today', exists (select 1 from public.study_similar_runs x
                        where x.exam_id = p_exam and x.scope = 'sheet' and x.created_at >= v_day and study_private.similar_today(x)),
      'joined', (select x.id from public.study_similar_runs x
                  where x.exam_id = p_exam and x.scope = 'sheet' and x.status = 'running' and study_private.similar_live(x.id)
                  order by x.created_at desc limit 1),
      'pages', coalesce((select to_jsonb(array_agg(distinct pg order by pg)) from unnest(ids[1:24]) u
                           cross join lateral unnest(study_private.similar_fig_pages(u)) pg), '[]'));
  end if;
  raise exception 'bad scope';
end;
$$;

-- ── The start (op "similar", the member's token and the server key) ──
-- After the op reserved the run's worst case under the member (p_reserve:
-- study_reserve, kind 'similar', ref 'ask'; the 80% line, the member's 40%,
-- 10 a day). Under ONE lock per sheet ('similar:' || sheet) it decides per
-- root: item: 6 a root ('max'), or a run making this root now ({joined});
-- sheet: once a day ('today'), a run of the whole sheet making now
-- ({joined}), and the roots of p_items still without a twin ('nothing to
-- make'). Then under the group's budget lock: the similar line, this
-- month's 'similar' spend (other runs' reservations included) and this
-- worst case within p_cap (STUDY_SIMILAR_MONTHLY_USD; 'similar_cap'). The
-- run, its jobs (similar_job_roots() roots a job; an item's run one job), its practice set in
-- section L (the sheet's one set, "שאלות דומות · {sheet}"; created by the
-- first run) and the kick. Returns {run_id, set_id, jobs, items, per,
-- server} or {joined}. The op settles p_reserve at $0 on any refusal.
create or replace function public.study_similar_begin(p_exam uuid, p_items uuid[], p_scope text, p_per int, p_reserve bigint,
  p_worst numeric, p_cap numeric, p_urls jsonb default null, p_until timestamptz default null, p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  e      public.study_exams;
  u      public.study_usage;
  r      uuid;
  roots  uuid[];
  v_per  int := least(2, greatest(1, coalesce(p_per, 1)));
  v_run  uuid;
  v_set  uuid;
  v_join uuid;
  v_sim  numeric;
  v_day  timestamptz := date_trunc('day', now() at time zone 'Asia/Jerusalem') at time zone 'Asia/Jerusalem';
  v_month timestamptz := date_trunc('month', now() at time zone 'utc') at time zone 'utc';
  k      int := 0;
  n      int := 0;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  e := study_private.similar_sheet(p_exam);
  if p_scope not in ('item', 'sheet') then raise exception 'bad scope'; end if;
  if coalesce(p_worst, 0) <= 0 or p_worst >= 100 or coalesce(p_cap, 0) <= 0 then raise exception 'bad request'; end if;
  if not study_private.similar_urls_ok(p_exam, p_urls) then raise exception 'bad urls'; end if;
  select * into u from public.study_usage x where x.id = p_reserve;
  if not found or u.group_id <> e.group_id or u.user_id is distinct from auth.uid() or u.kind <> 'similar' or u.settled_at is not null then
    raise exception 'bad reserve';
  end if;
  perform pg_advisory_xact_lock(hashtext('similar:' || p_exam::text));
  if p_scope = 'item' then
    if cardinality(coalesce(p_items, '{}')) <> 1 then raise exception 'bad request'; end if;
    r := study_private.similar_root(p_items[1]);
    if r is null or not exists (select 1 from public.study_questions q where q.id = r and q.exam_id = p_exam) then
      raise exception 'question not found';
    end if;
    if not study_private.similar_ok(r, p_exam) then raise exception 'not eligible'; end if;
    select x.id into v_join from public.study_similar_runs x
     where x.exam_id = p_exam and x.status = 'running' and r = any (x.items) and study_private.similar_live(x.id)
     order by x.created_at desc limit 1;
    if v_join is not null then return jsonb_build_object('joined', v_join); end if;
    if study_private.similar_count(r) >= 6 then raise exception 'max'; end if;
    v_per := least(v_per, 6 - study_private.similar_count(r));
    roots := array[r];
  else
    select x.id into v_join from public.study_similar_runs x
     where x.exam_id = p_exam and x.scope = 'sheet' and x.status = 'running' and study_private.similar_live(x.id)
     order by x.created_at desc limit 1;
    if v_join is not null then return jsonb_build_object('joined', v_join); end if;
    if exists (select 1 from public.study_similar_runs x
                where x.exam_id = p_exam and x.scope = 'sheet' and x.created_at >= v_day and study_private.similar_today(x)) then
      raise exception 'today';
    end if;
    v_per := 1;
    roots := array(select o from study_private.similar_open_roots(p_exam) o
                    where p_items is null or o = any (p_items) limit 24);
    if cardinality(roots) = 0 then raise exception 'nothing to make'; end if;
  end if;
  -- The similar line (OD20), under the group's budget lock, as study_reserve's.
  perform pg_advisory_xact_lock(hashtext('study_budget:' || e.group_id::text));
  select coalesce(sum(x.cost_usd), 0) into v_sim from public.study_usage x
   where x.group_id = e.group_id and x.kind = 'similar' and x.created_at >= v_month and x.id <> p_reserve;
  if v_sim + p_worst > p_cap then raise exception 'similar_cap'; end if;

  insert into public.study_similar_runs (group_id, exam_id, scope, items, per, reserve_id, reserved_usd, created_by)
  values (e.group_id, p_exam, p_scope, roots, v_per, p_reserve, round(p_worst, 4), auth.uid())
  returning id into v_run;
  while k < cardinality(roots) loop
    insert into study_private.similar_jobs (run_id, group_id, items)
    values (v_run, e.group_id, roots[k + 1 : k + study_private.similar_job_roots()]);
    k := k + study_private.similar_job_roots();
    n := n + 1;
  end loop;
  insert into study_private.similar_queue (run_id, group_id, urls, urls_until)
  values (v_run, e.group_id, p_urls, case when p_urls is not null then least(coalesce(p_until, now() + interval '48 hours'), now() + interval '48 hours') end);
  -- The sheet's practice set in section L (one a sheet; OD10). Without L, the twins stay with their sheet.
  if to_regprocedure('study_private.qset_for_similar(uuid,uuid,uuid,uuid,text,integer)') is not null then
    select s.id into v_set from public.study_qsets s
     where s.group_id = e.group_id and s.kind = 'sheet' and s.exam_id = p_exam and s.deleted_at is null
     order by s.created_at limit 1;
    if v_set is null then
      v_set := study_private.qset_for_similar(e.group_id, p_exam, v_run, auth.uid(), left('שאלות דומות · ' || e.title, 80),
                                              cardinality(roots) * v_per);
    end if;
    update public.study_similar_runs set set_id = v_set where id = v_run;
  end if;
  perform study_private.similar_dispatch(v_run, true);
  return jsonb_build_object('run_id', v_run, 'set_id', v_set, 'jobs', n, 'items', cardinality(roots), 'per', v_per,
                            'server', study_private.server_on());
end;
$$;

-- ── The worker (the key alone; the phone's fallback with the member's token too) ──

-- Jobs that died after their claim get 4 attempts, then fail as 'lost'.
create or replace function study_private.similar_give_up(p_run uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
begin
  update study_private.similar_jobs j
     set status = 'failed', error = 'lost', retry_at = null, lease_id = null, lease_until = null, updated_at = now()
   where j.run_id = p_run and j.status = 'running' and j.attempts >= 4 and j.lease_until <= now();
  if found then perform study_private.similar_advance(p_run); end if;
end;
$$;

-- The next job of a run under a 330-second lease, or null: the switch
-- 'similar' (or 'sheets', 'exams') is off, the run is over or fully
-- charged, the sheet was deleted, or the group runs its three already
-- (summaries and exams count, group_live). Returns the job, the run's
-- money (reserved, charged, left), the sheet, its lecture's slides (for
-- the slides' solver) and each root with its parts, its key and solution,
-- its figures' pages with the run's links while they are good, and the
-- stems of the twins it has (so a new one is not the same case).
create or replace function public.study_claim_similar(p_run uuid, p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  x        public.study_similar_runs;
  e        public.study_exams;
  j        study_private.similar_jobs;
  q        study_private.similar_queue;
  v_lease  uuid := gen_random_uuid();
  v_server boolean := auth.uid() is null;
  v_links  boolean;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  select * into x from public.study_similar_runs r where r.id = p_run;
  if not found then return null; end if;
  if not v_server and not coalesce(public.study_is_member(x.group_id), false) then raise exception 'forbidden'; end if;
  perform 1 from public.study_groups g where g.id = x.group_id for update;   -- study_claim and study_claim_exam take the same lock
  perform study_private.similar_give_up(p_run);
  select * into x from public.study_similar_runs r where r.id = p_run;
  select * into e from public.study_exams z where z.id = x.exam_id;
  if x.status <> 'running' or e.deleted_at is not null
     or not study_private.feature_on('similar') or not study_private.feature_on('sheets') or not study_private.feature_on('exams') then
    return null;
  end if;
  if v_server then update study_private.similar_queue set kicks_since_claim = 0 where run_id = p_run; end if;
  if x.charged_usd >= x.reserved_usd then return null; end if;
  if study_private.group_live(x.group_id) >= study_private.exam_cap(x.group_id) then return null; end if;
  -- A job whose every root got its twins (its save went in, its finish did not) is done.
  update study_private.similar_jobs z set status = 'done', error = null, retry_at = null, lease_id = null, lease_until = null, updated_at = now()
   where z.run_id = p_run and z.status <> 'done' and z.items <@ z.done_roots
     and (z.status <> 'running' or z.lease_until <= now());
  if found then perform study_private.similar_advance(p_run); end if;
  select * into j from study_private.similar_jobs z
   where z.run_id = p_run and not (z.items <@ z.done_roots)
     and (z.status = 'pending'
          or (z.status = 'running' and z.lease_until <= now() and z.attempts < 4)
          or (z.status = 'failed' and z.attempts < 4 and z.retry_at is not null and (not v_server or z.retry_at <= now())))
   order by z.created_at, z.id
   limit 1 for update;
  if not found then return null; end if;
  update study_private.similar_jobs z
     set status = 'running', lease_id = v_lease, lease_until = now() + interval '330 seconds', attempts = z.attempts + 1,
         retry_at = null, updated_at = now()
   where z.id = j.id;
  select * into q from study_private.similar_queue z where z.run_id = p_run;
  v_links := q.urls is not null and q.urls_until > now() + interval '10 minutes';
  return jsonb_build_object(
    'job', j.id, 'lease', v_lease, 'attempt', j.attempts + 1, 'last_error', j.error,
    'run', jsonb_build_object('id', x.id, 'scope', x.scope, 'per', x.per, 'requester', x.created_by,
                              'reserved_usd', x.reserved_usd, 'charged_usd', x.charged_usd,
                              'left_usd', greatest(0, x.reserved_usd - x.charged_usd), 'set_id', x.set_id),
    'exam', jsonb_build_object('id', e.id, 'group_id', e.group_id, 'title', e.title, 'course', e.course, 'lecture_id', e.lecture_id),
    'lecture', (select jsonb_build_object('id', l.id, 'title', l.title, 'lecturer', l.lecturer, 'slides', l.slides)
                  from public.study_lectures l where l.id = e.lecture_id and l.deleted_at is null),
    'items', coalesce((select jsonb_agg(jsonb_build_object(
        'id', r.id, 'label', coalesce(r.no_label, r.exam_no::text), 'kind', r.kind, 'vignette', r.vignette,
        'topic', r.topic, 'aspect', r.aspect, 'difficulty', r.difficulty,
        'parts', (select jsonb_agg(jsonb_build_object(
                     'id', p.id, 'step', p.step, 'label', coalesce(p.no_label, p.exam_no::text), 'form', p.form,
                     'question', p.question, 'options', to_jsonb(p.options), 'prompts', coalesce(p.layout -> 'prompts', '[]'::jsonb),
                     'answer', k.answer, 'seq', to_jsonb(k.seq), 'num', k.num, 'num_unit', k.num_unit, 'num_tol', k.num_tol,
                     'explanations', to_jsonb(k.explanations), 'takeaway', k.takeaway, 'solution', k.solution,
                     'figures', to_jsonb(case when cardinality(coalesce(p.figures, '{}')) > 0 then p.figures
                                              when p.figure like 'pg:%' then array[p.figure] else '{}'::text[] end))
                   order by coalesce(p.step, 1), p.id)
                    from study_private.similar_parts(r.id) pid join public.study_questions p on p.id = pid
                    left join public.study_question_keys k on k.question_id = p.id),
        'pages', (select coalesce(jsonb_agg(jsonb_build_object('n', pg.n, 'path', pg.path, 'w', pg.w, 'h', pg.h,
                                                               'url', case when v_links then q.urls ->> pg.path end) order by pg.n), '[]'::jsonb)
                    from public.study_exam_pages pg
                   where pg.exam_id = e.id and pg.n = any (study_private.similar_fig_pages(r.id))),
        'twins', coalesce((select jsonb_agg(left(t.question, 400) order by t.created_at) from public.study_questions t
                            where t.source = 'twin' and t.twin_of = r.id), '[]'::jsonb))
      order by array_position(j.items, r.id))
      from public.study_questions r where r.id = any (j.items) and not (r.id = any (j.done_roots)) and r.retired_at is null), '[]'::jsonb));
end;
$$;

-- One model call of a job, charged to its run (design D20): a settled
-- 'similar' row (ref 'unit') in the requester's name, so the member's 40%
-- and the similar line count it, and the run's reservation lowered by as
-- much, so the two together never pass what was reserved. False when the
-- next call's worst case (p_next_worst) no longer fits what is left: the
-- job saves what passed and stops. 'forbidden', 'lease lost'.
create or replace function public.study_similar_charge(p_job uuid, p_lease uuid, p_model text, p_usage jsonb, p_cost numeric,
  p_next_worst numeric default 0, p_key text default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  j  study_private.similar_jobs;
  x  public.study_similar_runs;
  c  numeric := round(least(greatest(coalesce(p_cost, 0), 0), 99.99999), 5);
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  select * into j from study_private.similar_jobs z where z.id = p_job;
  if not found then raise exception 'lease lost'; end if;
  if auth.uid() is not null and not coalesce(public.study_is_member(j.group_id), false) then raise exception 'forbidden'; end if;
  if j.status <> 'running' or j.lease_id is distinct from p_lease then raise exception 'lease lost'; end if;
  select * into x from public.study_similar_runs r where r.id = j.run_id for update;
  insert into public.study_usage (group_id, user_id, kind, ref, model, usage, cost_usd, settled_at)
  values (x.group_id, x.created_by, 'similar', 'unit', left(p_model, 80), p_usage, c, now());
  update public.study_usage u set cost_usd = greatest(0, u.cost_usd - c)
   where u.id = x.reserve_id and u.settled_at is null;
  update public.study_similar_runs r set charged_usd = least(99, r.charged_usd + c), updated_at = now() where r.id = x.id;
  return x.charged_usd + c + greatest(coalesce(p_next_worst, 0), 0) <= x.reserved_usd;
end;
$$;

-- The checked twins of a job (each {root, check, reuse_figure, kind,
-- vignette, parts: [{form, question, options, prompts, answer, seq, num,
-- num_unit, num_tol, explanations, takeaway, solution}]}, one part per
-- part of its root, in order). A twin that does not keep its root's form,
-- option count or parts, or a root at its 6 (re-checked under the sheet's
-- lock), is dropped. Saved as source 'twin', twin_of the root's part,
-- from_exam the sheet, its sheet's lecture as ref_lecture, the root's
-- topic, aspect and difficulty, the requester as author; the key a 'twin'
-- key at confidence 3 with its worked solution. Then added to the sheet's
-- set (section L's qset_add_items). Returns {saved, dropped}.
create or replace function public.study_similar_save(p_job uuid, p_lease uuid, p_twins jsonb, p_dropped int default 0,
  p_skipped int default 0, p_model text default null, p_key text default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  j      study_private.similar_jobs;
  x      public.study_similar_runs;
  e      public.study_exams;
  t      jsonb;
  p      jsonb;
  r      public.study_questions;
  rp     public.study_questions;
  parts  uuid[];
  rk     public.study_question_keys;
  ok     boolean;
  n      int;
  i      int;
  v_ser  uuid;
  v_id   uuid;
  v_new  uuid[] := '{}';
  v_made int := 0;
  v_roots uuid[] := '{}';
  v_drop int := greatest(0, least(coalesce(p_dropped, 0), 200));
  opts   text[];
  prm    text[];
  sq     smallint[];
  expl   text[];
  ans    int;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  select * into j from study_private.similar_jobs z where z.id = p_job;
  if not found then raise exception 'lease lost'; end if;
  if auth.uid() is not null and not coalesce(public.study_is_member(j.group_id), false) then raise exception 'forbidden'; end if;
  if j.status <> 'running' or j.lease_id is distinct from p_lease then raise exception 'lease lost'; end if;
  if p_twins is null or jsonb_typeof(p_twins) <> 'array' or jsonb_array_length(p_twins) > 32 then raise exception 'bad twins'; end if;
  select * into x from public.study_similar_runs z where z.id = j.run_id;
  select * into e from public.study_exams z where z.id = x.exam_id;
  perform pg_advisory_xact_lock(hashtext('similar:' || x.exam_id::text));
  for t in select v from jsonb_array_elements(p_twins) v loop
    ok := jsonb_typeof(t) = 'object' and coalesce(t ->> 'root', '') ~* '^[0-9a-f-]{36}$'
          and coalesce(t ->> 'check', '') in ('recalc', 'blind', 'slides') and jsonb_typeof(t -> 'parts') = 'array';
    if ok then
      select * into r from public.study_questions z where z.id = (t ->> 'root')::uuid;
      ok := found and r.id = any (j.items) and not (r.id = any (j.done_roots)) and r.exam_id = x.exam_id and r.retired_at is null
            and study_private.similar_count(r.id) < 6;
    end if;
    if ok then
      parts := array(select study_private.similar_parts(r.id));
      ok := jsonb_array_length(t -> 'parts') = cardinality(parts)
            and char_length(coalesce(t ->> 'vignette', '')) <= 8000;
    end if;
    -- Every part keeps its root part's form and size (pure checks ran on the server; these are the database's).
    i := 0;
    while ok and i < coalesce(cardinality(parts), 0) loop
      p := t -> 'parts' -> i;
      select * into rp from public.study_questions z where z.id = parts[i + 1];
      opts := array(select jsonb_array_elements_text(coalesce(p -> 'options', '[]')));
      prm := array(select jsonb_array_elements_text(coalesce(p -> 'prompts', '[]')));
      ok := jsonb_typeof(p) = 'object' and p ->> 'form' is not distinct from rp.form
            and char_length(btrim(coalesce(p ->> 'question', ''))) between 5 and 4000
            and cardinality(opts) = cardinality(rp.options)
            and not exists (select 1 from unnest(opts) o where char_length(btrim(o)) not between 1 and 400)
            and (rp.form <> 'match' or cardinality(prm) = jsonb_array_length(coalesce(rp.layout -> 'prompts', '[]')))
            and char_length(coalesce(p ->> 'takeaway', '')) <= 600 and char_length(coalesce(p ->> 'solution', '')) <= 6000
            and (jsonb_typeof(p -> 'explanations') is distinct from 'array' or jsonb_array_length(p -> 'explanations') in (0, cardinality(opts)));
      if ok then
        sq := array(select (v)::smallint from jsonb_array_elements_text(coalesce(p -> 'seq', '[]')) v where v ~ '^[0-9]{1,2}$');
        ans := case when coalesce(p ->> 'answer', '') ~ '^[0-9]{1,2}$' then (p ->> 'answer')::int end;
        ok := case rp.form
                when 'one' then ans is not null and ans < cardinality(opts)
                when 'tf' then cardinality(sq) = cardinality(opts) and 1 >= all (sq)
                when 'match' then cardinality(sq) = cardinality(prm) and cardinality(opts) - 1 >= all (sq)
                                  and (select count(distinct v) from unnest(sq) v) = cardinality(sq)
                when 'order' then cardinality(sq) = cardinality(opts) and cardinality(opts) - 1 >= all (sq)
                                  and (select count(distinct v) from unnest(sq) v) = cardinality(sq)
                when 'numeric' then coalesce(p ->> 'num', '') ~ '^-?[0-9]{1,12}(\.[0-9]{1,12})?([eE][-+]?[0-9]{1,3})?$'
                                    and case when p ->> 'num_tol' is null then true
                                             when p ->> 'num_tol' ~ '^[0-9]{1,2}(\.[0-9]{1,4})?$' then (p ->> 'num_tol')::numeric <= 50
                                             else false end
                                    and char_length(coalesce(p ->> 'num_unit', '')) <= 30
                else false end;
      end if;
      i := i + 1;
    end loop;
    if not ok then
      v_drop := v_drop + 1;
      continue;
    end if;
    v_ser := case when cardinality(parts) > 1 then gen_random_uuid() end;
    for i in 0 .. cardinality(parts) - 1 loop
      p := t -> 'parts' -> i;
      select * into rp from public.study_questions z where z.id = parts[i + 1];
      opts := array(select btrim(o) from jsonb_array_elements_text(coalesce(p -> 'options', '[]')) o);
      prm := array(select btrim(o) from jsonb_array_elements_text(coalesce(p -> 'prompts', '[]')) o);
      insert into public.study_questions (group_id, source, from_exam, twin_of, twin_check, ref_lecture, kind, difficulty, vignette,
                                          question, options, form, layout, series, step, topic, aspect, figure, figures, page,
                                          has_key, model, created_by)
      values (x.group_id, 'twin', x.exam_id, rp.id, t ->> 'check',
              (select l.id from public.study_lectures l where l.id = coalesce(rp.ref_lecture, e.lecture_id) and l.deleted_at is null),
              case when btrim(coalesce(t ->> 'vignette', '')) <> '' then 'case' else 'mcq' end, r.difficulty,
              case when i = 0 or cardinality(parts) = 1 then btrim(coalesce(t ->> 'vignette', '')) else '' end,
              btrim(p ->> 'question'), opts, rp.form,
              case when rp.form = 'match' then jsonb_build_object('prompts', to_jsonb(prm)) end,
              v_ser, case when v_ser is not null then i + 1 end, r.topic, r.aspect,
              case when coalesce(t ->> 'reuse_figure', '') = 'true' then rp.figure else '' end,
              case when coalesce(t ->> 'reuse_figure', '') = 'true' then rp.figures else '{}'::text[] end,
              case when coalesce(t ->> 'reuse_figure', '') = 'true' then rp.page end,
              true, left(coalesce(p_model, ''), 80), x.created_by)
      returning id into v_id;
      sq := array(select (v)::smallint from jsonb_array_elements_text(coalesce(p -> 'seq', '[]')) v);
      expl := array(select jsonb_array_elements_text(coalesce(p -> 'explanations', '[]')));
      insert into public.study_question_keys (question_id, answer, seq, explanations, takeaway, key_origin, key_conf,
                                              num, num_unit, num_tol, solution, solution_origin, solution_conf)
      values (v_id, case when rp.form = 'one' then (p ->> 'answer')::int end,
              case when rp.form in ('tf', 'match', 'order') then sq end,
              case when cardinality(expl) = cardinality(opts) then expl else '{}'::text[] end,
              left(coalesce(p ->> 'takeaway', ''), 600), 'twin', 3,
              case when rp.form = 'numeric' then (p ->> 'num')::numeric end,
              case when rp.form = 'numeric' then nullif(left(btrim(coalesce(p ->> 'num_unit', '')), 30), '') end,
              case when rp.form = 'numeric' then coalesce((p ->> 'num_tol')::numeric, 1) end,
              nullif(left(btrim(coalesce(p ->> 'solution', '')), 6000), ''),
              case when btrim(coalesce(p ->> 'solution', '')) <> '' then 'twin' end,
              case when btrim(coalesce(p ->> 'solution', '')) <> '' then 3 end);
      v_new := v_new || v_id;
    end loop;
    v_made := v_made + 1;
    v_roots := v_roots || r.id;
  end loop;
  update study_private.similar_jobs z
     set made = z.made + v_made, dropped = z.dropped + v_drop, skipped = z.skipped + greatest(0, least(coalesce(p_skipped, 0), 8)),
         done_roots = array(select distinct u from unnest(z.done_roots || v_roots) u), updated_at = now()
   where z.id = p_job;
  update public.study_similar_runs z
     set made = z.made + v_made, dropped = z.dropped + v_drop, skipped_figs = z.skipped_figs + greatest(0, least(coalesce(p_skipped, 0), 8)),
         updated_at = now()
   where z.id = x.id;
  -- Into the sheet's set, in the order made (section L's helper; its size grows with it).
  if x.set_id is not null and cardinality(v_new) > 0
     and to_regprocedure('study_private.qset_add_items(uuid,uuid[])') is not null then
    perform study_private.qset_add_items(x.set_id, v_new);
    update public.study_qsets s set want = least(60, greatest(s.want, (select count(*)::int from public.study_qset_items i where i.set_id = s.id)))
     where s.id = x.set_id;
  end if;
  return jsonb_build_object('saved', v_made, 'dropped', v_drop);
end;
$$;

-- When a run has nothing left that will run: its status (done; stopped by
-- the switch, the reservation or a stale day; failed when nothing was
-- made and a job failed), its reservation settled at $0 (every real cost
-- is in its charge rows), its kicks gone, and its set made ready in
-- section L (qset_similar_done: the set's one notice to the group), or
-- removed when this run made it and nothing came. A whole-sheet run tells
-- its requester (section R's similar_ready) when it made something.
create or replace function study_private.similar_advance(p_run uuid)
returns void language plpgsql volatile security definer set search_path = public as $$
declare
  x   public.study_similar_runs;
  v_err text;
  v_status text;
begin
  select * into x from public.study_similar_runs r where r.id = p_run for update;
  if not found or x.status <> 'running' then return; end if;
  if study_private.similar_live(p_run) then return; end if;
  select j.error into v_err from study_private.similar_jobs j where j.run_id = p_run and j.status = 'failed' order by j.updated_at desc limit 1;
  v_status := case when not exists (select 1 from study_private.similar_jobs j where j.run_id = p_run and j.status <> 'done') then 'done'
                   when v_err in ('reserve_used', 'off', 'stale', 'budget', 'reserve', 'member_share') then 'stopped'
                   when x.made > 0 then 'done'
                   else 'failed' end;
  update public.study_similar_runs r set status = v_status, error = left(v_err, 200), updated_at = now() where r.id = p_run;
  update public.study_usage u set cost_usd = 0, settled_at = now(),
         usage = jsonb_build_object('similar_run', p_run, 'charged_usd', x.charged_usd)
   where u.id = x.reserve_id and u.settled_at is null;
  delete from study_private.similar_queue where run_id = p_run;
  if x.set_id is not null and to_regclass('public.study_qsets') is not null then
    if exists (select 1 from public.study_qset_items i where i.set_id = x.set_id) then
      if to_regprocedure('study_private.qset_similar_done(uuid)') is not null then
        perform study_private.qset_similar_done(x.set_id);
      end if;
    else
      update public.study_qsets s set deleted_at = now() where s.id = x.set_id and s.similar_run = p_run and s.deleted_at is null;
    end if;
  end if;
  if x.scope = 'sheet' and x.made > 0
     and to_regprocedure('study_private.notice_add(uuid,uuid,text,jsonb,jsonb,text,text,uuid,timestamptz)') is not null then
    perform study_private.notice_add(x.created_by, x.group_id, 'similar_ready',
      jsonb_strip_nulls(jsonb_build_object('k', x.made, 'kind', 'sheet',
                                           'course', nullif(left((select e.course from public.study_exams e where e.id = x.exam_id), 120), ''))),
      case when x.set_id is not null then jsonb_build_object('v', 'sets', 'k', x.set_id)
           else jsonb_build_object('v', 'exams', 'e', x.exam_id) end,
      'similar:' || p_run, 'similar:' || p_run, null, null);
  end if;
end;
$$;

-- A job's end (as study_finish_exam_job): a timeout, a refusal or an answer
-- that cannot be read gets one more try a minute later; a passing API
-- error is retried with backoff; 'reserve_used' (the run's money is spent)
-- and the switches end it. Then the run moves on, and the next job is kicked.
create or replace function public.study_finish_similar_job(p_job uuid, p_lease uuid, p_status text, p_error text default null,
  p_key text default null)
returns boolean language plpgsql volatile security definer set search_path = public as $$
declare
  j  study_private.similar_jobs;
  ok boolean;
begin
  if not study_private.is_worker(p_key) then raise exception 'forbidden'; end if;
  if p_status not in ('done', 'failed') then raise exception 'bad finish'; end if;
  select * into j from study_private.similar_jobs x where x.id = p_job;
  if not found then return false; end if;
  if auth.uid() is not null and not coalesce(public.study_is_member(j.group_id), false) then raise exception 'forbidden'; end if;
  update study_private.similar_jobs x
     set status = p_status, error = case when p_status = 'failed' then left(coalesce(p_error, 'failed'), 200) end,
         retry_at = case when p_status = 'done' then null
                         when p_error in ('timeout', 'refusal', 'unreadable', 'truncated', 'empty')
                           then case when x.attempts < 2 then now() + interval '1 minute' end
                         else study_private.retry_at('failed', p_error, x.attempts) end,
         lease_id = null, lease_until = null, updated_at = now()
   where x.id = p_job and x.lease_id = p_lease and x.status = 'running';
  ok := found;
  perform study_private.similar_advance(j.run_id);
  if ok then perform study_private.similar_dispatch(j.run_id, true); end if;
  return ok;
end;
$$;

-- ── The member's reads ──

-- The twins of an item's root (the item itself, one of its parts, or one
-- of its twins): their ids in the order made, without keys (practice
-- answers them as any question). Hidden when the sheet was deleted (an old
-- sheet's twins go with it), retired or hidden by two flags. Also the
-- room left (6 a root) and a run making some now.
create or replace function public.study_similar_of(p_question uuid)
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  r uuid;
  q public.study_questions;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  r := study_private.similar_root(p_question);
  select * into q from public.study_questions x where x.id = r;
  if not found or not coalesce(public.study_is_member(q.group_id), false) or q.exam_id is null
     or exists (select 1 from public.study_exams e where e.id = q.exam_id and e.deleted_at is not null) then
    raise exception 'question not found';
  end if;
  return jsonb_build_object(
    'root', r, 'exam_id', q.exam_id,
    'label', coalesce(q.no_label, q.exam_no::text),
    'twins', coalesce((select jsonb_agg(jsonb_build_object('id', t.id, 'form', t.form, 'series', t.series, 'step', t.step,
                                                           'check', t.twin_check, 'of', t.twin_of, 'created_at', t.created_at)
                                        order by t.created_at, coalesce(t.step, 1))
                         from public.study_questions t
                        where t.source = 'twin' and t.retired_at is null and t.hidden_at is null
                          and t.twin_of in (select study_private.similar_parts(r))), '[]'),
    'room', greatest(0, 6 - study_private.similar_count(r)),
    'running', (select x.id from public.study_similar_runs x
                 where x.exam_id = q.exam_id and x.status = 'running' and r = any (x.items) and study_private.similar_live(x.id)
                 order by x.created_at desc limit 1));
end;
$$;

-- ── Redefined from section S: the group's units at once ──
-- Writers and exam units holding a live lease (S's), plus similar jobs, so
-- summaries, exams and similar questions share the three of a group (two
-- while a lecture waits to be written: exam_cap).
create or replace function study_private.group_live(p_group uuid)
returns int language sql stable security definer set search_path = public as $$
  select ((select count(*) from public.study_sections s join public.study_lectures l on l.id = s.lecture_id
            where l.group_id = p_group and s.status = 'writing'
              and coalesce(s.lease_until, s.updated_at + interval '6 minutes') > now())
        + (select count(*) from public.study_recording_notes n join public.study_lectures l on l.id = n.lecture_id
            where l.group_id = p_group and n.status = 'writing' and n.lease_until > now())
        + (select count(*) from public.study_lectures l
            where l.group_id = p_group and l.status = 'outlining'
              and coalesce(l.lease_until, l.updated_at + interval '3 minutes') > now())
        + (select count(*) from study_private.exam_jobs j
            where j.group_id = p_group and j.status = 'running' and j.lease_until > now())
        + (select count(*) from study_private.similar_jobs j
            where j.group_id = p_group and j.status = 'running' and j.lease_until > now()))::int
$$;

-- ── The sweeper (its own pg_cron job, study-similar-dispatch; S's is untouched) ──
-- Kicks /api/study/work {similar: run} for each running run with a job the
-- caps allow now (2 minutes between the sweeper's kicks of one run, none
-- after 15 kicks nobody claimed). With a switch off it stops what holds no
-- live lease (the run ends 'stopped' and its reservation is let go); a run
-- still running after a day is stopped too ('stale').
create or replace function study_private.similar_dispatch(p_run uuid default null, p_now boolean default false)
returns int language plpgsql volatile security definer set search_path = public as $$
declare
  q record; v_url text; v_key text; v_n int; v_total int := 0;
  v_on boolean := study_private.feature_on('similar') and study_private.feature_on('sheets') and study_private.feature_on('exams');
begin
  for q in select r.id, r.group_id, r.created_at, sq.last_kick_at, sq.kicks_since_claim
             from public.study_similar_runs r left join study_private.similar_queue sq on sq.run_id = r.id
            where r.status = 'running' and (p_run is null or r.id = p_run) order by r.created_at loop
    perform study_private.similar_give_up(q.id);
    if not v_on or q.created_at < now() - interval '1 day'
       or exists (select 1 from public.study_exams e join public.study_similar_runs r on r.exam_id = e.id where r.id = q.id and e.deleted_at is not null) then
      update study_private.similar_jobs j
         set status = 'failed', error = case when q.created_at < now() - interval '1 day' then 'stale' else 'off' end,
             retry_at = null, updated_at = now()
       where j.run_id = q.id and (j.status in ('pending', 'failed') or (j.status = 'running' and j.lease_until <= now()))
         and j.status <> 'done' and not (j.status = 'failed' and j.retry_at is null);
      perform study_private.similar_advance(q.id);
      continue;
    end if;
    if not study_private.server_on() then continue; end if;
    select count(*) into v_n from study_private.similar_jobs j
     where j.run_id = q.id
       and (j.status = 'pending' or (j.status = 'running' and j.lease_until <= now() and j.attempts < 4)
            or (j.status = 'failed' and j.attempts < 4 and j.retry_at <= now()));
    v_n := least(v_n, study_private.exam_cap(q.group_id) - study_private.group_live(q.group_id));
    if v_n <= 0 or (not p_now and q.last_kick_at > now() - interval '2 minutes') or coalesce(q.kicks_since_claim, 0) >= 15 then
      continue;
    end if;
    v_url := rtrim(study_private.secret('study_site_url'), '/') || '/api/study/work';
    v_key := study_private.secret('study_worker_key');
    for i in 1..v_n loop
      perform net.http_post(
        url := v_url,
        body := jsonb_build_object('similar', q.id),
        headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_key),
        timeout_milliseconds := 10000);
    end loop;
    update study_private.similar_queue set last_kick_at = now(), kicks_since_claim = kicks_since_claim + v_n where run_id = q.id;
    v_total := v_total + v_n;
  end loop;
  return v_total;
end;
$$;

revoke all on function study_private.similar_job_roots(), study_private.similar_root(uuid), study_private.similar_parts(uuid), study_private.similar_count(uuid),
  study_private.similar_ok(uuid, uuid), study_private.similar_fig_pages(uuid), study_private.similar_sheet(uuid),
  study_private.similar_live(uuid), study_private.similar_open_roots(uuid), study_private.similar_urls_ok(uuid, jsonb),
  study_private.similar_give_up(uuid), study_private.similar_advance(uuid), study_private.similar_dispatch(uuid, boolean),
  study_private.group_live(uuid) from public;
revoke all on function public.study_similar_plan(uuid, uuid, text), public.study_similar_of(uuid),
  public.study_similar_begin(uuid, uuid[], text, int, bigint, numeric, numeric, jsonb, timestamptz, text),
  public.study_claim_similar(uuid, text), public.study_similar_charge(uuid, uuid, text, jsonb, numeric, numeric, text),
  public.study_similar_save(uuid, uuid, jsonb, int, int, text, text),
  public.study_finish_similar_job(uuid, uuid, text, text, text) from public, anon;
grant execute on function public.study_similar_plan(uuid, uuid, text), public.study_similar_of(uuid) to authenticated;
-- The op's (the member's token and the server key inside).
grant execute on function public.study_similar_begin(uuid, uuid[], text, int, bigint, numeric, numeric, jsonb, timestamptz, text) to authenticated;
-- The worker's: the key inside; the worker calls as anon, the phone's fallback with the member's token.
grant execute on function public.study_claim_similar(uuid, text), public.study_similar_charge(uuid, uuid, text, jsonb, numeric, numeric, text),
  public.study_similar_save(uuid, uuid, jsonb, int, int, text, text), public.study_finish_similar_job(uuid, uuid, text, text, text)
  to anon, authenticated;

-- ── A numeric answer inside a practice set's attempt (section L) ──
-- The sheet's set (kind 'sheet') holds numeric twins; their answer is O 2's
-- study_answer_value, so inside a round of a set it goes through this
-- wrapper as section L's study_qset_answer does a choice: the attempt
-- checked (L's qset_attempt_open), the same answer and reply, then the
-- attempt stamped on the row this call added (L's qset_stamp), so the set's
-- score and its group numbers count it. 'off' without section L; L's and
-- O 2's refusals as theirs.
create or replace function public.study_qset_answer_value(p_attempt uuid, p_question uuid, p_value numeric, p_mode text default 'exam',
  p_ms int default null)
returns jsonb language plpgsql volatile security definer set search_path = public as $$
declare
  v_before uuid[];
  r        jsonb;
begin
  if auth.uid() is null then raise exception 'not signed in'; end if;
  if to_regprocedure('study_private.qset_attempt_open(uuid,uuid)') is null
     or to_regprocedure('study_private.qset_stamp(uuid,uuid,uuid[])') is null then
    raise exception 'off';
  end if;
  perform study_private.qset_attempt_open(p_attempt, p_question);
  v_before := array(select y.id from public.study_answers y where y.user_id = auth.uid() and y.question_id = p_question);
  r := public.study_answer_value(p_question, p_value, p_mode, p_ms);
  perform study_private.qset_stamp(p_attempt, p_question, v_before);
  return r;
end;
$$;
revoke all on function public.study_qset_answer_value(uuid, uuid, numeric, text, int) from public, anon;
grant execute on function public.study_qset_answer_value(uuid, uuid, numeric, text, int) to authenticated;

-- The similar sweeper: every minute, its own job (only with pg_cron).
do $$
begin
  if to_regnamespace('cron') is not null then
    perform cron.schedule('study-similar-dispatch', '* * * * *', 'select study_private.similar_dispatch()');
  end if;
end $$;

-- Section R's kind (reserved there: the requester's own, pushed, held 90 s
-- like a past exam's), registered again here so its settings are O's.
do $$
begin
  if to_regclass('study_private.notice_kinds') is not null then
    insert into study_private.notice_kinds (kind, cat, ttl, delay, push) values ('similar_ready', 'mine', '2 days', '90 seconds', true)
    on conflict (kind) do update set cat = excluded.cat, ttl = excluded.ttl, delay = excluded.delay, push = excluded.push;
  end if;
end $$;

insert into study_private.schema_sections (section, version) values ('O', 3)
on conflict (section) do update set version = excluded.version, loaded_at = now();
-- ════ END SECTION O ════
